// src/Component/UserList.js
import React, { useEffect, useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import {
  fetchUsersAsync,
  updateUserAsync,
  deleteUserAsync,
  selectUsersState,
} from "./userSlice";
import "./UserList.css";

function UserList() {
  const dispatch = useDispatch();
  const { users, loading, error } = useSelector(selectUsersState);

  // Edit state
  const [editUserId, setEditUserId] = useState(null);
  const [editData, setEditData] = useState({});

  // New user state
  const [newUser, setNewUser] = useState({
    username: "",
    email: "",
    first_name: "",
    last_name: "",
    profile: { bio: "", phone: "" },
    is_active: true,
    password: "",
  });

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const usersPerPage = 5;
  const totalPages = Math.ceil(users.length / usersPerPage);

  useEffect(() => {
    dispatch(fetchUsersAsync());
  }, [dispatch]);

  // --- Handlers ---
  const handleEditClick = (user) => {
    setEditUserId(user.id);
    setEditData({ ...user });
  };

  const handleChange = (key, value, isNew = false) => {
    if (key === "bio" || key === "phone") {
      if (isNew) {
        setNewUser({ ...newUser, profile: { ...newUser.profile, [key]: value } });
      } else {
        setEditData({ ...editData, profile: { ...editData.profile, [key]: value } });
      }
    } else if (key === "is_active") {
      if (isNew) setNewUser({ ...newUser, [key]: value });
      else setEditData({ ...editData, [key]: value });
    } else {
      if (isNew) setNewUser({ ...newUser, [key]: value });
      else setEditData({ ...editData, [key]: value });
    }
  };

  const handleSave = async () => {
    if (!editUserId) return;
    try {
      await dispatch(updateUserAsync(editData)).unwrap();
      await dispatch(fetchUsersAsync());
      setEditUserId(null);
      alert("✅ User updated successfully");
    } catch (err) {
      console.error("❌ Update failed:", err);
      alert("Update failed on backend.");
    }
  };

  const handleDelete = async (id) => {
    if (!id) return;
    if (window.confirm("Are you sure you want to delete this user?")) {
      try {
        await dispatch(deleteUserAsync(id)).unwrap();
        await dispatch(fetchUsersAsync());
        alert("User deleted successfully!");
      } catch (err) {
        console.error(err);
        alert("Delete failed: " + err.message);
      }
    }
  };

  const handleAddUser = async () => {
    const token = localStorage.getItem("token");
    try {
      const res = await fetch("http://127.0.0.1:8000/api/users/", {
        method: "POST",
        headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
        body: JSON.stringify(newUser),
      });
      if (!res.ok) throw new Error("Failed to create user");
      await dispatch(fetchUsersAsync());
      setNewUser({
        username: "",
        email: "",
        first_name: "",
        last_name: "",
        profile: { bio: "", phone: "" },
        is_active: true,
        password: "",
      });
      alert("✅ User added successfully");
    } catch (err) {
      console.error(err);
      alert("Add user failed: " + err.message);
    }
  };

  // Pagination controls
  const paginateUsers = users.slice((currentPage - 1) * usersPerPage, currentPage * usersPerPage);

  if (loading) return <p>Loading users...</p>;
  if (error) return <p style={{ color: "red" }}>Error: {error}</p>;

  return (
    <div className="userlist-container">
      <h2>User Management</h2>

      {/* --- Add New User Form --- */}
      <div className="new-user-form">
        <h3>Add New User</h3>
        <input placeholder="Username" value={newUser.username} onChange={(e) => handleChange("username", e.target.value, true)} />
        <input placeholder="Email" value={newUser.email} onChange={(e) => handleChange("email", e.target.value, true)} />
        <input placeholder="First Name" value={newUser.first_name} onChange={(e) => handleChange("first_name", e.target.value, true)} />
        <input placeholder="Last Name" value={newUser.last_name} onChange={(e) => handleChange("last_name", e.target.value, true)} />
        <input placeholder="Bio" value={newUser.profile.bio} onChange={(e) => handleChange("bio", e.target.value, true)} />
        <input placeholder="Phone" value={newUser.profile.phone} onChange={(e) => handleChange("phone", e.target.value, true)} />
        <input placeholder="Password" type="password" value={newUser.password} onChange={(e) => handleChange("password", e.target.value, true)} />
        <select value={newUser.is_active ? "Active" : "Inactive"} onChange={(e) => handleChange("is_active", e.target.value === "Active", true)}>
          <option>Active</option>
          <option>Inactive</option>
        </select>
        <button onClick={handleAddUser}>Add User</button>
      </div>

      {/* --- User Table --- */}
      <table className="user-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Username</th>
            <th>Email</th>
            <th>First</th>
            <th>Last</th>
            <th>Bio</th>
            <th>Phone</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {paginateUsers.length > 0 ? (
            paginateUsers.map((u) => (
              <tr key={u.id}>
                <td>{u.id}</td>
                <td>{editUserId === u.id ? <input value={editData.username} onChange={(e) => handleChange("username", e.target.value)} /> : u.username}</td>
                <td>{editUserId === u.id ? <input value={editData.email} onChange={(e) => handleChange("email", e.target.value)} /> : u.email}</td>
                <td>{editUserId === u.id ? <input value={editData.first_name} onChange={(e) => handleChange("first_name", e.target.value)} /> : u.first_name}</td>
                <td>{editUserId === u.id ? <input value={editData.last_name} onChange={(e) => handleChange("last_name", e.target.value)} /> : u.last_name}</td>
                <td>{editUserId === u.id ? <input value={editData.profile?.bio} onChange={(e) => handleChange("bio", e.target.value)} /> : u.profile?.bio}</td>
                <td>{editUserId === u.id ? <input value={editData.profile?.phone} onChange={(e) => handleChange("phone", e.target.value)} /> : u.profile?.phone}</td>
                <td>{editUserId === u.id ? <select value={editData.is_active ? "Active" : "Inactive"} onChange={(e) => handleChange("is_active", e.target.value === "Active")}><option>Active</option><option>Inactive</option></select> : u.is_active ? "Active" : "Inactive"}</td>
                <td>
                  {editUserId === u.id ? (
                    <>
                      <button onClick={handleSave}>Save</button>
                      <button onClick={() => setEditUserId(null)}>Cancel</button>
                    </>
                  ) : (
                    <>
                      <button onClick={() => handleEditClick(u)}>Edit</button>
                      <button onClick={() => handleDelete(u.id)}>Delete</button>
                    </>
                  )}
                </td>
              </tr>
            ))
          ) : (
            <tr><td colSpan="9" style={{ textAlign: "center" }}>No users found</td></tr>
          )}
        </tbody>
      </table>

      {/* --- Pagination --- */}
      {totalPages > 1 && (
        <div className="pagination">
          <button disabled={currentPage === 1} onClick={() => setCurrentPage(currentPage - 1)}>Prev</button>
          <span>Page {currentPage} of {totalPages}</span>
          <button disabled={currentPage === totalPages} onClick={() => setCurrentPage(currentPage + 1)}>Next</button>
        </div>
      )}
    </div>
  );
}

export default UserList;
